/* quick hand sketch: one line (points 0..100) → a fast, loose pen line.
   Small shift / turn per line, slow wobble, ends that go a little past (and closed shapes that do not close exactly). */
window.PICS2.sketch=function(pts,R){R=R||Math.random;if(!pts||pts.length<2)return pts||[];
  const d=[pts[0]];for(let i=1;i<pts.length;i++){const a=pts[i-1],b=pts[i],n=Math.max(1,Math.ceil(Math.hypot(b[0]-a[0],b[1]-a[1])/2.5));for(let j=1;j<=n;j++)d.push([a[0]+(b[0]-a[0])*j/n,a[1]+(b[1]-a[1])*j/n])}
  let len=0;for(let i=1;i<d.length;i++)len+=Math.hypot(d[i][0]-d[i-1][0],d[i][1]-d[i-1][1]);
  const closed=d.length>4&&Math.hypot(d[0][0]-d.at(-1)[0],d[0][1]-d.at(-1)[1])<3;
  if(closed){const k=Math.min(d.length-1,2+Math.floor(R()*3));for(let i=1;i<=k;i++)d.push(d[i])}   // go a little past the start
  const dir=(a,b)=>{const l=Math.hypot(b[0]-a[0],b[1]-a[1])||1;return[(b[0]-a[0])/l,(b[1]-a[1])/l]};
  const s0=dir(d[1],d[0]),s1=dir(d.at(-2),d.at(-1)),e0=1+R()*2.5*Math.min(1,len/20),e1=1+R()*3*Math.min(1,len/20);
  d.unshift([d[0][0]+s0[0]*e0,d[0][1]+s0[1]*e0]);d.push([d.at(-1)[0]+s1[0]*e1,d.at(-1)[1]+s1[1]*e1]);
  let cx=0,cy=0;for(const p of d){cx+=p[0];cy+=p[1]}cx/=d.length;cy/=d.length;
  const big=Math.min(1,len/40),rot=(R()-.5)*.07,sc=1+(R()-.5)*.06,tx=(R()-.5)*2.4,ty=(R()-.5)*2.4,
    a1=(.6+R()*1.1)*big+.3,f1=.05+R()*.07,p1=R()*6,a2=(.6+R()*1.1)*big+.3,f2=.05+R()*.07,p2=R()*6,c=Math.cos(rot),s=Math.sin(rot);
  return d.map(([x,y],i)=>{const u=(x-cx)*sc,v=(y-cy)*sc;return[cx+u*c-v*s+tx+a1*Math.sin(i*f1+p1),cy+u*s+v*c+ty+a2*Math.sin(i*f2+p2)]})};
